// Cross-check of the Python tiled transparency log (szl_khipu_scholar/tlog)
// against independent Go implementations:
//   - golang.org/x/mod/sumdb/note   (signed notes)
//   - golang.org/x/mod/sumdb/tlog   (tile hash reader, tree hash, proofs)
//   - github.com/transparency-dev/merkle (RFC 6962 hasher, proof verification)
//   - github.com/transparency-dev/formats/log (checkpoint parsing)
//   - github.com/transparency-dev/tessera/client (tlog-tiles client)
//
// The fixture is generated by tests/test_tlog_interop.py in a temp directory
// with throwaway keys. This test is skipped unless TLOG_FIXTURE is set.
package interop

import (
	"bytes"
	"context"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	fmtlog "github.com/transparency-dev/formats/log"
	"github.com/transparency-dev/merkle/proof"
	"github.com/transparency-dev/merkle/rfc6962"
	"github.com/transparency-dev/tessera/client"
	"golang.org/x/mod/sumdb/note"
	"golang.org/x/mod/sumdb/tlog"
)

type fixture struct {
	Origin      string             `json:"origin"`
	VKey        string             `json:"vkey"`
	LogDir      string             `json:"log_dir"`
	Sizes       []uint64           `json:"sizes"`
	Checkpoints map[string]string  `json:"checkpoints"` // size -> signed note (text)
	Roots       map[string]string  `json:"roots"`       // size -> hex root
	Inclusion   map[string][][]any `json:"inclusion"`   // size -> [[index, [hex...]], ...]
	Consistency []consistencyCase  `json:"consistency"`
	Out         string             `json:"out"`
}

type consistencyCase struct {
	Old   uint64   `json:"old"`
	New   uint64   `json:"new"`
	Proof []string `json:"proof"`
}

func entryFor(i uint64) []byte {
	return []byte(fmt.Sprintf(`{"n":%d,"note":"khipu receipt bytes are opaque"}`, i))
}

func load(t *testing.T) *fixture {
	p := os.Getenv("TLOG_FIXTURE")
	if p == "" {
		t.Skip("TLOG_FIXTURE not set")
	}
	raw, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	var f fixture
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	return &f
}

func unhex(t *testing.T, s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func unhexAll(t *testing.T, ss []string) [][]byte {
	out := make([][]byte, len(ss))
	for i, s := range ss {
		out[i] = unhex(t, s)
	}
	return out
}

func sz(n uint64) string { return strconv.FormatUint(n, 10) }

// 1. Signed notes: sumdb/note opens every Python checkpoint; tamper and wrong-key cases fail.
func TestSumdbNoteOpensPythonCheckpoints(t *testing.T) {
	f := load(t)
	v, err := note.NewVerifier(f.VKey)
	if err != nil {
		t.Fatalf("NewVerifier(vkey): %v", err)
	}
	for _, n := range f.Sizes {
		msg := []byte(f.Checkpoints[sz(n)])
		opened, err := note.Open(msg, note.VerifierList(v))
		if err != nil {
			t.Fatalf("size %d: note.Open: %v", n, err)
		}
		if len(opened.Sigs) != 1 || opened.UnverifiedSigs != nil {
			t.Fatalf("size %d: want 1 verified sig, got %d (unverified %d)", n, len(opened.Sigs), len(opened.UnverifiedSigs))
		}
		var cp fmtlog.Checkpoint
		if _, err := cp.Unmarshal([]byte(opened.Text)); err != nil {
			t.Fatalf("size %d: checkpoint Unmarshal: %v", n, err)
		}
		if cp.Origin != f.Origin || cp.Size != n || hex.EncodeToString(cp.Hash) != f.Roots[sz(n)] {
			t.Fatalf("size %d: checkpoint fields disagree with fixture: %+v", n, cp)
		}
		if !bytes.Equal(cp.Marshal(), []byte(opened.Text)) {
			t.Fatalf("size %d: Go re-marshal of checkpoint differs byte-for-byte from Python text", n)
		}
		// tampered text must not verify
		bad := bytes.Replace(msg, []byte("\n"+sz(n)+"\n"), []byte("\n"+sz(n+1)+"\n"), 1)
		if _, err := note.Open(bad, note.VerifierList(v)); err == nil {
			t.Fatalf("size %d: tampered checkpoint verified", n)
		}
	}
	_, other, err := note.GenerateKey(nil, f.Origin)
	if err != nil {
		t.Fatal(err)
	}
	ov, err := note.NewVerifier(other)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := note.Open([]byte(f.Checkpoints[sz(f.Sizes[0])]), note.VerifierList(ov)); err == nil {
		t.Fatal("a checkpoint verified under an unrelated key")
	}
}

// tileReader maps sumdb tiles (H=8) onto the tlog-tiles layout written by Python.
type tileReader struct{ dir string }

func (r tileReader) Height() int                     { return 8 }
func (r tileReader) SaveTiles([]tlog.Tile, [][]byte) {}
func (r tileReader) ReadTiles(ts []tlog.Tile) ([][]byte, error) {
	out := make([][]byte, len(ts))
	for i, t := range ts {
		p := tilePath(uint64(t.L), uint64(t.N), t.W)
		b, err := os.ReadFile(filepath.Join(r.dir, p))
		if err != nil {
			return nil, err
		}
		out[i] = b
	}
	return out, nil
}

func tileIndex(n uint64) string {
	var groups []string
	for {
		groups = append([]string{fmt.Sprintf("%03d", n%1000)}, groups...)
		n /= 1000
		if n == 0 {
			break
		}
	}
	for i := 0; i < len(groups)-1; i++ {
		groups[i] = "x" + groups[i]
	}
	return strings.Join(groups, "/")
}

func tilePath(l, n uint64, w int) string {
	s := fmt.Sprintf("tile/%d/%s", l, tileIndex(n))
	if w != 256 {
		s += fmt.Sprintf(".p/%d", w)
	}
	return s
}

//  2. sumdb/tlog reads the Python tiles, verifies them against the signed root,
//     and its own proofs equal the Python proofs byte for byte.
func TestSumdbTlogReadsPythonTiles(t *testing.T) {
	f := load(t)
	for _, n := range f.Sizes {
		root := unhex(t, f.Roots[sz(n)])
		var h tlog.Hash
		copy(h[:], root)
		tree := tlog.Tree{N: int64(n), Hash: h}
		hr := tlog.TileHashReader(tree, tileReader{dir: f.LogDir})
		got, err := tlog.TreeHash(int64(n), hr)
		if err != nil {
			t.Fatalf("size %d: TreeHash from Python tiles: %v", n, err)
		}
		if got != h {
			t.Fatalf("size %d: sumdb TreeHash %x != checkpoint root %x", n, got, h)
		}
		for _, row := range f.Inclusion[sz(n)] {
			idx := int64(row[0].(float64))
			var py []string
			for _, x := range row[1].([]any) {
				py = append(py, x.(string))
			}
			gp, err := tlog.ProveRecord(int64(n), idx, hr)
			if err != nil {
				t.Fatalf("size %d idx %d: ProveRecord: %v", n, idx, err)
			}
			if len(gp) != len(py) {
				t.Fatalf("size %d idx %d: proof length Go %d Python %d", n, idx, len(gp), len(py))
			}
			for i := range gp {
				if hex.EncodeToString(gp[i][:]) != py[i] {
					t.Fatalf("size %d idx %d: proof element %d differs", n, idx, i)
				}
			}
			if err := tlog.CheckRecord(gp, int64(n), h, idx, tlog.RecordHash(entryFor(uint64(idx)))); err != nil {
				t.Fatalf("size %d idx %d: CheckRecord on Go proof: %v", n, idx, err)
			}
			// Python's proof, checked by Go's verifier
			pyh := make(tlog.RecordProof, len(py))
			for i, s := range py {
				copy(pyh[i][:], unhex(t, s))
			}
			if err := tlog.CheckRecord(pyh, int64(n), h, idx, tlog.RecordHash(entryFor(uint64(idx)))); err != nil {
				t.Fatalf("size %d idx %d: CheckRecord on Python proof: %v", n, idx, err)
			}
		}
	}
	for _, c := range f.Consistency {
		newRoot := unhex(t, f.Roots[sz(c.New)])
		var nh tlog.Hash
		copy(nh[:], newRoot)
		hr := tlog.TileHashReader(tlog.Tree{N: int64(c.New), Hash: nh}, tileReader{dir: f.LogDir})
		gp, err := tlog.ProveTree(int64(c.New), int64(c.Old), hr)
		if err != nil {
			t.Fatalf("%d->%d: ProveTree: %v", c.Old, c.New, err)
		}
		if len(gp) != len(c.Proof) {
			t.Fatalf("%d->%d: proof length Go %d Python %d", c.Old, c.New, len(gp), len(c.Proof))
		}
		for i := range gp {
			if hex.EncodeToString(gp[i][:]) != c.Proof[i] {
				t.Fatalf("%d->%d: proof element %d differs", c.Old, c.New, i)
			}
		}
		var oh tlog.Hash
		copy(oh[:], unhex(t, f.Roots[sz(c.Old)]))
		if err := tlog.CheckTree(gp, int64(c.New), nh, int64(c.Old), oh); err != nil {
			t.Fatalf("%d->%d: CheckTree: %v", c.Old, c.New, err)
		}
	}
}

//  3. transparency-dev/merkle verifies Python's inclusion and consistency proofs,
//     and rejects mutated ones.
func TestTransparencyDevMerkleVerifiesPythonProofs(t *testing.T) {
	f := load(t)
	h := rfc6962.DefaultHasher
	nIncl, nCons, nNeg := 0, 0, 0
	for _, n := range f.Sizes {
		root := unhex(t, f.Roots[sz(n)])
		for _, row := range f.Inclusion[sz(n)] {
			idx := uint64(row[0].(float64))
			var py [][]byte
			for _, x := range row[1].([]any) {
				py = append(py, unhex(t, x.(string)))
			}
			leaf := h.HashLeaf(entryFor(idx))
			if err := proof.VerifyInclusion(h, idx, n, leaf, py, root); err != nil {
				t.Fatalf("size %d idx %d: VerifyInclusion: %v", n, idx, err)
			}
			nIncl++
			wrongIdx := (idx + 1) % n
			if n > 1 && proof.VerifyInclusion(h, wrongIdx, n, leaf, py, root) == nil {
				t.Fatalf("size %d: proof accepted for wrong index", n)
			} else if n > 1 {
				nNeg++
			}
			if len(py) > 0 {
				mut := make([][]byte, len(py))
				for i := range py {
					mut[i] = append([]byte(nil), py[i]...)
				}
				mut[0][0] ^= 1
				if proof.VerifyInclusion(h, idx, n, leaf, mut, root) == nil {
					t.Fatalf("size %d idx %d: mutated proof accepted", n, idx)
				}
				if proof.VerifyInclusion(h, idx, n, leaf, py[:len(py)-1], root) == nil {
					t.Fatalf("size %d idx %d: truncated proof accepted", n, idx)
				}
				nNeg += 2
			}
		}
	}
	for _, c := range f.Consistency {
		py := unhexAll(t, c.Proof)
		r1, r2 := unhex(t, f.Roots[sz(c.Old)]), unhex(t, f.Roots[sz(c.New)])
		if err := proof.VerifyConsistency(h, c.Old, c.New, py, r1, r2); err != nil {
			t.Fatalf("%d->%d: VerifyConsistency: %v", c.Old, c.New, err)
		}
		nCons++
		if len(py) > 0 {
			mut := make([][]byte, len(py))
			for i := range py {
				mut[i] = append([]byte(nil), py[i]...)
			}
			mut[len(mut)-1][5] ^= 0x80
			if proof.VerifyConsistency(h, c.Old, c.New, mut, r1, r2) == nil {
				t.Fatalf("%d->%d: mutated consistency proof accepted", c.Old, c.New)
			}
			nNeg++
		}
	}
	t.Logf("transparency-dev/merkle: %d inclusion proofs, %d consistency proofs verified; %d negative cases rejected", nIncl, nCons, nNeg)
}

//  4. Level-0 tiles and entry bundles agree: every bundle entry hashes (RFC 6962)
//     to the matching level-0 tile hash, using Go's hasher and an independent parser.
func TestEntryBundlesHashToLevel0Tiles(t *testing.T) {
	f := load(t)
	n := f.Sizes[len(f.Sizes)-1]
	h := rfc6962.DefaultHasher
	count := uint64(0)
	for b := uint64(0); b*256 < n; b++ {
		w := 256
		if rem := n - b*256; rem < 256 {
			w = int(rem)
		}
		suffix := ""
		if w != 256 {
			suffix = fmt.Sprintf(".p/%d", w)
		}
		bundle, err := os.ReadFile(filepath.Join(f.LogDir, "tile/entries/"+tileIndex(b)+suffix))
		if err != nil {
			t.Fatal(err)
		}
		tile, err := os.ReadFile(filepath.Join(f.LogDir, tilePath(0, b, w)))
		if err != nil {
			t.Fatal(err)
		}
		if len(tile) != 32*w {
			t.Fatalf("level-0 tile %d has %d bytes, want %d", b, len(tile), 32*w)
		}
		off := 0
		for i := 0; i < w; i++ {
			l := int(binary.BigEndian.Uint16(bundle[off:]))
			off += 2
			e := bundle[off : off+l]
			off += l
			if !bytes.Equal(e, entryFor(b*256+uint64(i))) {
				t.Fatalf("bundle %d entry %d content mismatch", b, i)
			}
			if !bytes.Equal(h.HashLeaf(e), tile[32*i:32*i+32]) {
				t.Fatalf("bundle %d entry %d does not hash to its tile hash", b, i)
			}
			count++
		}
		if off != len(bundle) {
			t.Fatalf("bundle %d has %d trailing bytes", b, len(bundle)-off)
		}
	}
	if count != n {
		t.Fatalf("checked %d entries, want %d", count, n)
	}
	t.Logf("%d entries across bundles hash to the level-0 tiles", count)
}

//  5. The tlog-tiles client from transparency-dev/tessera: verifies the checkpoint,
//     builds proofs from the Python tiles, and reads entry bundles. Once from the
//     filesystem and once over HTTP against a local httptest server.
func tesseraRun(t *testing.T, f *fixture, ff client.FileFetcher, httpFetcher *client.HTTPFetcher) {
	ctx := context.Background()
	v, err := note.NewVerifier(f.VKey)
	if err != nil {
		t.Fatal(err)
	}
	var readCP client.CheckpointFetcherFunc = ff.ReadCheckpoint
	readTile := client.TileFetcherFunc(ff.ReadTile)
	readBundle := client.EntryBundleFetcherFunc(ff.ReadEntryBundle)
	if httpFetcher != nil {
		readCP = httpFetcher.ReadCheckpoint
		readTile = httpFetcher.ReadTile
		readBundle = httpFetcher.ReadEntryBundle
	}
	cp, _, _, err := client.FetchCheckpoint(ctx, readCP, v, f.Origin)
	if err != nil {
		t.Fatalf("FetchCheckpoint: %v", err)
	}
	last := f.Sizes[len(f.Sizes)-1]
	if cp.Size != last || hex.EncodeToString(cp.Hash) != f.Roots[sz(last)] {
		t.Fatalf("served checkpoint is not the latest one: size %d", cp.Size)
	}
	pb, err := client.NewProofBuilder(ctx, cp.Size, readTile)
	if err != nil {
		t.Fatal(err)
	}
	h := rfc6962.DefaultHasher
	checked := 0
	for _, row := range f.Inclusion[sz(last)] {
		idx := uint64(row[0].(float64))
		gp, err := pb.InclusionProof(ctx, idx)
		if err != nil {
			t.Fatalf("InclusionProof(%d): %v", idx, err)
		}
		for i, x := range row[1].([]any) {
			if hex.EncodeToString(gp[i]) != x.(string) {
				t.Fatalf("idx %d: tessera proof element %d differs from Python", idx, i)
			}
		}
		if err := proof.VerifyInclusion(h, idx, cp.Size, h.HashLeaf(entryFor(idx)), gp, cp.Hash); err != nil {
			t.Fatalf("idx %d: %v", idx, err)
		}
		checked++
	}
	for _, c := range f.Consistency {
		if c.New != last {
			continue
		}
		gp, err := pb.ConsistencyProof(ctx, c.Old, c.New)
		if err != nil {
			t.Fatalf("ConsistencyProof(%d,%d): %v", c.Old, c.New, err)
		}
		for i := range c.Proof {
			if hex.EncodeToString(gp[i]) != c.Proof[i] {
				t.Fatalf("%d->%d: tessera consistency element %d differs from Python", c.Old, c.New, i)
			}
		}
		checked++
	}
	for _, b := range []uint64{0, 1, (last - 1) / 256} {
		eb, err := client.GetEntryBundle(ctx, readBundle, b, cp.Size)
		if err != nil {
			t.Fatalf("GetEntryBundle(%d): %v", b, err)
		}
		for i, e := range eb.Entries {
			if !bytes.Equal(e, entryFor(b*256+uint64(i))) {
				t.Fatalf("bundle %d entry %d mismatch", b, i)
			}
		}
		checked++
	}
	t.Logf("tessera tlog-tiles client: %d proof/bundle checks passed against checkpoint size %d", checked, cp.Size)
}

func TestTesseraClientFileFetcher(t *testing.T) {
	f := load(t)
	tesseraRun(t, f, client.FileFetcher{Root: f.LogDir}, nil)
}

func TestTesseraClientHTTPFetcher(t *testing.T) {
	f := load(t)
	srv := httptest.NewServer(http.FileServer(http.Dir(f.LogDir)))
	defer srv.Close()
	u, _ := url.Parse(srv.URL + "/")
	hf, err := client.NewHTTPFetcher(u, srv.Client())
	if err != nil {
		t.Fatal(err)
	}
	tesseraRun(t, f, client.FileFetcher{}, hf)
}

//  6. Go signs, Python verifies: a checkpoint signed by sumdb/note with a
//     throwaway Go key, written for the Python test to open.
func TestGoSignedCheckpointForPython(t *testing.T) {
	f := load(t)
	if f.Out == "" {
		t.Skip("no output dir")
	}
	skey, vkey, err := note.GenerateKey(nil, "go.example/receipts-log")
	if err != nil {
		t.Fatal(err)
	}
	s, err := note.NewSigner(skey)
	if err != nil {
		t.Fatal(err)
	}
	n := f.Sizes[len(f.Sizes)-1]
	cp := fmtlog.Checkpoint{Origin: "go.example/receipts-log", Size: n, Hash: unhex(t, f.Roots[sz(n)])}
	msg, err := note.Sign(&note.Note{Text: string(cp.Marshal())}, s)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(f.Out, "go_checkpoint.txt"), msg, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(f.Out, "go_vkey.txt"), []byte(vkey), 0o600); err != nil {
		t.Fatal(err)
	}
	// the spec's published example, an independent known-answer check of Go's side
	const specV = "example.com/foo+530d903a+AekyeRrm56hApGFkyQR4ZCbV54Id2LKaANYcrnKv3U2k"
	const specNote = "This is an example message.\n\n\u2014 example.com/foo Uw2QOkn8srV1yJGh2VYRlL1Tnagv1YEq6TfXppzi2ONncAlTgK7Ztg1ERYNZXsYjOBH3mFXmRKuwHjG1Yu72IneyaQM=\n"
	sv, err := note.NewVerifier(specV)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := note.Open([]byte(specNote), note.VerifierList(sv)); err != nil {
		t.Fatalf("spec example note: %v", err)
	}
}
